461	// CreateHandover 由交班班次向同岗位接班班次发起交接。
462	// 重复向同一接班班次发起返回已有记录（ErrHandoverExists）；该承诺在接班班次
463	// 随后结束、事项已在后续班次关闭或继续流转后仍然成立，返回保存的原交接内容，
464	// 不重新挑选清单、不重新接收或移动事项、不追加经过。改换接班对象报
465	// ErrHandoverTarget 并指出原接班班次，无论新对象是否结束都不产生第二条交接。
466	// 不存在的班次编号与交给自身始终按各自错误拒绝；同岗位及接班班次尚未结束等
467	// 要求仅对首次发起生效。
468	// 只有本地数据保存成功才算发起完成：首次发起的输入与班次状态均合法、实际进入
469	// 保存阶段后写盘失败时，内存变更随快照一并回滚，返回原保存错误与零值交接结果
470	// （编号、岗位、两班编号为空，发起时间为零值，完成时间为空，清单没有事项），
471	// 不把尚未保存的编号、发起时间、清单或空清单的完成时间当作发起结果；失败尝试
472	// 不占用交接编号，也不留下已指定接班对象的关系。
473	func (svc *Service) CreateHandover(fromShiftID, toShiftID string) (Handover, error) {
474		fromShiftID = clean(fromShiftID)
475		toShiftID = clean(toShiftID)
476	
477		var result Handover
478		// saved 标记业务变更是否已完整执行、只待落盘：此后出现的错误只能是保存
479		// 阶段失败，而不是业务拒绝。
480		saved := false
481		err := svc.store.mutate(func(d *Data) error {
482			from, _ := findShift(d, fromShiftID)
483			to, _ := findShift(d, toShiftID)
484			if from == nil {
485				return fmt.Errorf("%w：交班班次 %s", ErrNotFound, fromShiftID)
486			}
487			if to == nil {
488				return fmt.Errorf("%w：接班班次 %s", ErrNotFound, toShiftID)
489			}
490			if from.ID == to.ID {
491				return fmt.Errorf("%w：交班班次与接班班次不能都是 %s", ErrSameShift, from.ID)
492			}
493			// 同一交班班次只能指定一个接班对象。重复发起（包括接班班次随后已
494			// 结束、事项已在后续班次关闭或继续流转的情况）一律返回保存的原记录，
495			// 不重新接收事项、不追加经过；改换为另一个确实存在的接班对象（无论其
496			// 是否结束、是否同岗位）都按改换对象报错并指出原接班班次，且不能生成
497			// 第二条交接。该判定先于同岗位、接班班次状态等首次发起校验；编号不
498			// 存在与交给自身的校验仍在其前。
499			for i := range d.Handovers {
500				if d.Handovers[i].FromShiftID == from.ID {
501					existing := &d.Handovers[i]
502					// 即使以“已存在”错误返回，交出的也是独立副本，调用方改动
503					// 不影响系统保存的原交接记录。
504					result = cloneHandover(*existing)
505					if existing.ToShiftID != to.ID {
506						return fmt.Errorf("%w：交班班次 %s 已指定接班班次 %s，不能改换为 %s",
507							ErrHandoverTarget, from.ID, existing.ToShiftID, to.ID)
508					}
509					return fmt.Errorf("%w：交接 %s", ErrHandoverExists, existing.ID)
510				}
511			}
512	
513			if from.Position != to.Position {
514				return fmt.Errorf("%w：班次 %s（%s）不能交给其他岗位 %s（%s）",
515					ErrPositionMismatch, from.ID, from.Position, to.ID, to.Position)
516			}
517	
518			// 以下为首次发起的要求：接班班次尚未结束、开始时间不早于交班班次、
519			// 交班班次已经结束，重叠区间须有说明。
520			if to.Closed {
521				return fmt.Errorf("%w：接班班次 %s 已结束，不能交接", ErrShiftClosed, to.ID)
522			}
523			if to.Start.Before(from.Start) {
524				return fmt.Errorf("%w：接班班次 %s 开始时间 %s 早于交班班次 %s 开始时间 %s",
525					ErrInvalidInput, to.ID, to.Start.Format(time.RFC3339),
526					from.ID, from.Start.Format(time.RFC3339))
527			}
528			if !from.Closed {
529				return fmt.Errorf("%w：交班班次 %s 尚未结束，结束班次后未关闭事项才成为交接清单",
530					ErrShiftNotClosed, from.ID)
531			}
532			if intervalsOverlap(from.Start, from.End, to.Start, to.End) && !hasNote(d, from.ID, to.ID) {
533				return fmt.Errorf("%w：交班班次 %s 与接班班次 %s 时间区间重叠，须先填写重叠说明",
534					ErrOverlap, from.ID, to.ID)
535			}
536	
537			entries := []HandoverEntry{}
538			for i := range d.Items {
539				it := &d.Items[i]
540				if it.CurrentShiftID == from.ID && !it.Closed {
541					entries = append(entries, HandoverEntry{
542						ItemID:      it.ID,
543						Content:     it.Content,
544						Severity:    it.Severity,
545						Constraints: it.Constraints,
546						FollowOwner: it.FollowOwner,
547						Status:      EntryPending,
548					})
549				}
550			}
551			sort.Slice(entries, func(i, j int) bool { return entries[i].ItemID < entries[j].ItemID })
552	
553			d.HandoverSeq++
554			now := svc.now()
555			h := Handover{
556				ID:          fmt.Sprintf("H%03d", d.HandoverSeq),
557				Position:    from.Position,
558				FromShiftID: from.ID,
559				ToShiftID:   to.ID,
560				CreatedAt:   now,
561				Entries:     entries,
562			}
563			if len(entries) == 0 {
564				// 空清单直接完成。
565				h.CompletedAt = &now
566			}
567			d.Handovers = append(d.Handovers, h)
568			result = cloneHandover(h)
569			saved = true
570			return nil
571		})
572		if err != nil {
573			if saved {
574				// 业务校验全部通过、实际进入保存阶段后失败：内存已随快照回滚，
575				// 不能把尚未保存的新交接（编号、发起时间、清单与空清单的完成时间）
576				// 当作发起结果交给调用方。
577				return Handover{}, err
578			}
579			// 业务拒绝：重复发起与改换对象仍按承诺返回保存的原记录。
580			return result, err
581		}
582		return result, nil
583	}
584	
585	// ProcessEntry 由接班人逐项处理交接事项，须填写操作人。
586	// action 为 confirm（确认接收）、return（退回，须填原因）或 track（继续跟踪，须填跟踪说明和后续负责人）。
587	// 已退回项表示等待交班人补充，只有在原交接记录上成功重新提交、恢复待处理后才能再次
588	// 确认、继续跟踪或退回；未重新提交前直接处理一律返回状态错误，且不改变任何数据。
589	// 最后一项成功接收使整份交接首次全部明确接收时，完成时间记为本次成功处理时间；
590	// 若记录里存在补齐前误写（或零值）的旧完成时间，一并以本次时间覆盖。本次处理失败、
591	// 退回或仍有未接收项时不写完成时间，交接不能提前完成。
592	func (svc *Service) ProcessEntry(handoverID, itemID string, action EntryAction, operator, reason, trackingNote, nextFollowOwner string) (Handover, error) {
593		handoverID = clean(handoverID)
594		itemID = clean(itemID)
595		operator = clean(operator)
596		reason = clean(reason)
597		trackingNote = clean(trackingNote)
598		nextFollowOwner = clean(nextFollowOwner)
599	
600		if action != ActionConfirm && action != ActionReturn && action != ActionTrack {
601			return Handover{}, fmt.Errorf("%w：未知操作 %q", ErrInvalidInput, action)
602		}
603		if err := requireNonEmpty("操作人", operator); err != nil {
604			return Handover{}, err
605		}
606	
607		var result Handover
608		err := svc.store.mutate(func(d *Data) error {
609			h, _ := findHandover(d, handoverID)
610			if h == nil {
611				return fmt.Errorf("%w：交接 %s", ErrNotFound, handoverID)
612			}
613			e, _ := findEntry(h, itemID)
614			if e == nil {
615				return fmt.Errorf("%w：交接 %s 中没有事项 %s", ErrNotFound, h.ID, itemID)
616			}
617			if e.Status.Received() {
618				return fmt.Errorf("%w：事项 %s 已%s，不能重复处理或退回",
619					ErrHandoverState, e.ItemID, e.Status.Label())
620			}
621			if e.Status == EntryReturned {
622				// 退回表示等待交班人补充：必须先在原交接记录上补充说明并重新提交，
623				// 该项恢复待处理后才能再次确认、继续跟踪或退回。即使本次填写了
624				// 操作人、退回原因或跟踪说明，也不能跳过这一步。
625				return fmt.Errorf("%w：事项 %s 已退回，正等待交班人补充说明并在原交接记录 %s 上重新提交；请先完成补充并重新提交后再处理",
626					ErrHandoverState, e.ItemID, h.ID)
627			}
628			switch action {
629			case ActionReturn:
630				if err := requireNonEmpty("退回原因", reason); err != nil {
631					return err
632				}
633			case ActionTrack:
634				if err := requireNonEmpty("跟踪说明", trackingNote); err != nil {
635					return err
636				}
637				if err := requireNonEmpty("后续负责人", nextFollowOwner); err != nil {
638					return err
639				}
640			}
641	
642			now := svc.now()
643			switch action {
644			case ActionConfirm:
645				e.Status = EntryConfirmed
646			case ActionTrack:
647				e.Status = EntryTracking
648				e.TrackingNote = trackingNote
649				e.FollowOwner = nextFollowOwner
650			case ActionReturn:
651				e.Status = EntryReturned
652				e.Rounds = append(e.Rounds, ReturnRound{
653					Seq:            len(e.Rounds) + 1,
654					ReturnedAt:     now,
655					ReturnOperator: operator,
656					Reason:         reason,
657				})
658			}
659			e.Operator = operator
660			e.ProcessedAt = &now
661	
662			if action != ActionReturn {
663				// 确认与继续跟踪都进入接班班次的未关闭清单，保留原编号与历史。
664				if it, _ := findItem(d, e.ItemID); it != nil && it.CurrentShiftID == h.FromShiftID {
665					it.CurrentShiftID = h.ToShiftID
666					if !contains(it.ShiftIDs, h.ToShiftID) {
667						it.ShiftIDs = append(it.ShiftIDs, h.ToShiftID)
668					}
669					detail := receivedDetailText(h, action, e.Status.Label(), trackingNote, nextFollowOwner)
670					if action == ActionTrack {
671						// 继续跟踪指定新的后续负责人，回写到事项并保留跟踪说明。
672						it.FollowOwner = nextFollowOwner
673					}
674					it.Events = append(it.Events, ItemEvent{At: now, Kind: "received", Operator: operator, Detail: detail})
675				}
676			}
677	
678			if h.Completed() {
679				// 完成时间记录这份交接真正接收齐全部事项的时刻：以最后一次成功
680				// 接收（确认或继续跟踪）的处理时间为准。旧数据可能在清单仍有结果
681				// 缺失、无法识别、待处理或退回项时就误写过完成时间（或只留下零值）：
682				// 接班人逐项补齐、整份交接首次全部明确接收时，用本次成功处理时间
683				// 覆盖那个旧时间，不能沿用补齐前的时刻；旧时间缺失（nil）时同样在
684				// 本次补上。未全部接收（如本次退回、仍有异常结果项）时不写入，
685				// 交接保持未完成。正常流程与空清单在首次全部接收时写入，之后已接收
686				// 项无法再处理，完成时间不会被改写。
687				h.CompletedAt = &now
688			}
689			// 返回独立副本：调用方保留的处理结果（含逐项处理时间、退回/补充记录
690			// 与完成时间）不与系统保存的交接共享内存。
691			result = cloneHandover(*h)
692			return nil
693		})
694		return result, err
695	}
696	
697	// validProcessedAt 报告处理时间是否真实记录：nil 或零值
698	// （0001-01-01T00:00:00Z）都视为未记录，不推测补齐。
699	func validProcessedAt(t *time.Time) bool { return t != nil && !t.IsZero() }
700	
701	func contains(xs []string, x string) bool {
702		for _, v := range xs {
703			if v == x {
704				return true
705			}
706		}
707		return false
708	}
709	
710	// ResubmitReturned 由交班人对退回项追加非空说明并在同一交接记录上重新提交；
711	// 补充写入最近一次退回记录（保留该轮原因、退回人和退回时间，并记录补充人、
712	// 补充时间与重新提交时间），以前各轮说明不覆盖。只有该项恢复待处理，当前结果的
713	// 接班处理人与处理时间显示为尚未处理；原文、严重程度、限制条件不变，事项仍留在
714	// 交班班次，同一交接的其他事项不受影响。重新提交本身不表示接收。
715	// 对待处理、已确认或继续跟踪的事项重新提交报状态错误，不写入补充说明。
716	func (svc *Service) ResubmitReturned(handoverID, itemID, operator, supplement string) (Handover, error) {
717		handoverID = clean(handoverID)
718		itemID = clean(itemID)
719		operator = clean(operator)
720		supplement = clean(supplement)
721		if err := requireNonEmpty("操作人", operator); err != nil {
722			return Handover{}, err
723		}
724		if err := requireNonEmpty("补充说明", supplement); err != nil {
725			return Handover{}, err
726		}
727	
728		var result Handover
729		err := svc.store.mutate(func(d *Data) error {
730			h, _ := findHandover(d, handoverID)
731			if h == nil {
732				return fmt.Errorf("%w：交接 %s", ErrNotFound, handoverID)
733			}
734			e, _ := findEntry(h, itemID)
735			if e == nil {
736				return fmt.Errorf("%w：交接 %s 中没有事项 %s", ErrNotFound, h.ID, itemID)
737			}
738			if e.Status != EntryReturned {
739				return fmt.Errorf("%w：事项 %s 当前状态为 %s，只有退回项可以补充说明后重新提交",
740					ErrHandoverState, e.ItemID, e.Status.Label())
741			}
742			if len(e.Rounds) == 0 {
743				return fmt.Errorf("%w：事项 %s 缺少退回记录", ErrHandoverState, e.ItemID)
744			}
745			round := &e.Rounds[len(e.Rounds)-1]
746			if round.ResubmittedAt != nil {
747				return fmt.Errorf("%w：事项 %s 已重新提交，等待接班人处理", ErrHandoverState, e.ItemID)
748			}
749			now := svc.now()
750			round.Supplement = supplement
751			round.SupplementOperator = operator
752			round.SupplementAt = &now
753			round.ResubmittedAt = &now
754			// 仅这一个事项恢复待处理：当前结果的接班处理人与处理时间显示为
755			// 尚未处理；上一轮退回信息仍完整保留在 Rounds 历史中。
756			e.Status = EntryPending
757			e.Operator = ""
758			e.ProcessedAt = nil
759			// 返回独立副本：调用方保留的重新提交结果不与系统保存的交接共享内存。
760			result = cloneHandover(*h)
761			return nil
762		})
763		return result, err
764	}
765	
766	// GetShift 按编号查询班次。返回独立副本：改动结果不影响系统保存的记录。
767	func (svc *Service) GetShift(id string) (Shift, error) {
768		sh, _ := findShift(&svc.store.data, clean(id))
769		if sh == nil {
770			return Shift{}, fmt.Errorf("%w：班次 %s", ErrNotFound, id)
771		}
772		return cloneShift(*sh), nil
773	}
774	
775	// ListShifts 返回全部班次，按编号排序；每个班次都是独立副本。
776	func (svc *Service) ListShifts() []Shift {
777		out := make([]Shift, len(svc.store.data.Shifts))
778		for i, sh := range svc.store.data.Shifts {
779			out[i] = cloneShift(sh)
780		}
781		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
782		return out
783	}
784	
785	// GetItem 按稳定编号查询事项。返回独立副本：流经班次、历史事件与关闭时间
786	// 都与存储中的记录脱离，改动结果不影响系统保存的记录。
787	func (svc *Service) GetItem(id string) (Item, error) {
788		it, _ := findItem(&svc.store.data, clean(id))
789		if it == nil {
790			return Item{}, fmt.Errorf("%w：事项 %s", ErrNotFound, id)
791		}
792		return cloneItem(*it), nil
793	}
794	
795	// GetHandover 按编号查询交接。返回独立副本：清单各项（含处理时间与历次
796	// 退回/补充记录）与完成时间都与存储中的记录脱离，改动结果不影响系统保存的记录。
797	func (svc *Service) GetHandover(id string) (Handover, error) {
798		h, _ := findHandover(&svc.store.data, clean(id))
799		if h == nil {
800			return Handover{}, fmt.Errorf("%w：交接 %s", ErrNotFound, id)
801		}
802		return cloneHandover(*h), nil
803	}
804	
805	// ListHandovers 返回全部交接记录，按编号排序；每份交接都是独立副本。
806	func (svc *Service) ListHandovers() []Handover {
807		out := make([]Handover, len(svc.store.data.Handovers))
808		for i, h := range svc.store.data.Handovers {
809			out[i] = cloneHandover(h)
810		}
811		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
812		return out
813	}
814	
815	// OverlapNotes 返回涉及指定班次的全部重叠说明。
816	func (svc *Service) OverlapNotes(shiftID string) []OverlapNote {
817		shiftID = clean(shiftID)
818		out := []OverlapNote{}
819		for _, n := range svc.store.data.Notes {
820			if n.ShiftA == shiftID || n.ShiftB == shiftID {
821				out = append(out, n)
822			}
823		}
824		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
825		return out
826	}
827	
828	// cloneTimePtr 复制时间指针，nil 保持 nil。
829	func cloneTimePtr(t *time.Time) *time.Time {
830		if t == nil {
831			return nil
832		}
833		v := *t
834		return &v
835	}
836	
837	// cloneItem 深拷贝事项：流经班次、历史事件与关闭时间都与存储中的记录脱离。
838	func cloneItem(it Item) Item {
839		out := it
840		out.ShiftIDs = append([]string(nil), it.ShiftIDs...)
841		out.Events = append([]ItemEvent(nil), it.Events...)
842		out.ClosedAt = cloneTimePtr(it.ClosedAt)
843		return out
844	}
845	
846	// cloneCloseItemSnapshot 深拷贝结束时事项快照（含关闭时间指针）。
847	func cloneCloseItemSnapshot(s CloseItemSnapshot) CloseItemSnapshot {
848		out := s
849		out.ClosedAt = cloneTimePtr(s.ClosedAt)
850		return out
851	}
852	
853	// cloneCloseRecord 深拷贝班次结束时记录；nil 保持 nil，
854	// 空清单仍是非 nil 记录，与缺少结束时记录的旧数据相区别。
855	func cloneCloseRecord(rec *ShiftCloseRecord) *ShiftCloseRecord {
856		if rec == nil {
857			return nil
858		}
859		out := &ShiftCloseRecord{}
860		if rec.Items != nil {
861			out.Items = make([]CloseItemSnapshot, len(rec.Items))
862			for i, s := range rec.Items {
863				out.Items[i] = cloneCloseItemSnapshot(s)
864			}
865		}
866		return out
867	}
868	
869	// cloneShift 深拷贝班次：关闭时间与结束时记录都与存储中的记录脱离。
870	func cloneShift(sh Shift) Shift {
871		out := sh
872		out.ClosedAt = cloneTimePtr(sh.ClosedAt)
873		out.CloseRecord = cloneCloseRecord(sh.CloseRecord)
874		return out
875	}
876	
877	// cloneEntry 深拷贝交接单项：处理时间与历次退回/补充记录都与存储中的记录脱离。
878	func cloneEntry(e HandoverEntry) HandoverEntry {
879		out := e
880		out.ProcessedAt = cloneTimePtr(e.ProcessedAt)
881		if e.Rounds != nil {
882			out.Rounds = make([]ReturnRound, len(e.Rounds))
883			for i, r := range e.Rounds {
884				out.Rounds[i] = r
885				out.Rounds[i].SupplementAt = cloneTimePtr(r.SupplementAt)
886				out.Rounds[i].ResubmittedAt = cloneTimePtr(r.ResubmittedAt)
887			}
888		}
889		return out
890	}
891	
892	// cloneHandover 深拷贝交接记录：完成时间与清单各项都与存储中的记录脱离。
893	func cloneHandover(h Handover) Handover {
894		out := h
895		out.CompletedAt = cloneTimePtr(h.CompletedAt)
896		if h.Entries != nil {
897			out.Entries = make([]HandoverEntry, len(h.Entries))
898			for i, e := range h.Entries {
899				out.Entries[i] = cloneEntry(e)
900			}
901		}
902		return out
903	}
904	
905	// ShiftReport 按班次汇总完整事项、关闭情况、接班对象、每项交接当前结果与历次退回/补充说明。
906	// 进行中的班次展示当前事项；已结束班次展示结束时冻结的事项记录，
907	// 旧数据中缺少结束时记录的班次只展示当前事项并标明历史不完整。
908	// 返回的报告是查询当时的独立副本：班次信息、事项清单、结束时记录、最新状态
909	// 对照、关联交接与各项结果（含关闭时间、处理时间与历次退回补充记录）全部深拷贝，
910	// 调用方改动报告不影响系统保存的数据与其他已取得的报告，系统随后的正常处理
911	// 也不会改写这份报告；再次查询才反映最新内容。
912	func (svc *Service) ShiftReport(shiftID string) (ShiftReport, error) {
913		shiftID = clean(shiftID)
914		d := &svc.store.data
915		rep := ShiftReport{Results: map[string][]EntryView{}, LatestItems: map[string]Item{}}
916		sh, _ := findShift(d, shiftID)
917		if sh == nil {
918			return ShiftReport{}, fmt.Errorf("%w：班次 %s", ErrNotFound, shiftID)
919		}
920		rep.Shift = cloneShift(*sh)
921	
922		for _, n := range d.Notes {
923			if n.ShiftA == sh.ID || n.ShiftB == sh.ID {
924				rep.OverlapNotes = append(rep.OverlapNotes, n)
925			}
926		}
927		sort.Slice(rep.OverlapNotes, func(i, j int) bool { return rep.OverlapNotes[i].ID < rep.OverlapNotes[j].ID })
928	
929		switch {
930		case !sh.Closed:
931			// 进行中的班次：事项可继续修改、关闭，展示当前信息。
932			rep.Items = currentItemsOfShift(d, sh.ID)
933		case sh.CloseRecord != nil:
934			// 已结束且有结束时记录：展示冻结的结束时信息，并对照最新状态。
935			rep.ItemsAtClose = true
936			rep.CloseItems = make([]CloseItemSnapshot, len(sh.CloseRecord.Items))
937			for i, s := range sh.CloseRecord.Items {
938				rep.CloseItems[i] = cloneCloseItemSnapshot(s)
939			}
940			sort.Slice(rep.CloseItems, func(i, j int) bool { return rep.CloseItems[i].ItemID < rep.CloseItems[j].ItemID })
941			for _, s := range rep.CloseItems {
942				if it, _ := findItem(d, s.ItemID); it != nil {
943					rep.LatestItems[s.ItemID] = cloneItem(*it)
944				}
945			}
946		default:
947			// 旧数据：结束时未留下记录，只能展示当前信息，不能宣称是结束时事实。
948			rep.HistoryIncomplete = true
949			rep.Items = currentItemsOfShift(d, sh.ID)
950		}
951		sort.Slice(rep.Items, func(i, j int) bool { return rep.Items[i].ID < rep.Items[j].ID })
952		for i := range rep.Items {
953			rep.Items[i] = cloneItem(rep.Items[i])
954		}
955	
956		for i := range d.Handovers {
957			h := &d.Handovers[i]
958			involved := h.FromShiftID == sh.ID || h.ToShiftID == sh.ID
959			if !involved {
960				continue
961			}
962			if h.FromShiftID == sh.ID {
963				cp := cloneHandover(*h)
964				rep.Outgoing = &cp
965			}
966			if h.ToShiftID == sh.ID {
967				rep.Incoming = append(rep.Incoming, cloneHandover(*h))
968			}
969			for j := range h.Entries {
970				rep.Results[h.Entries[j].ItemID] = append(rep.Results[h.Entries[j].ItemID], EntryView{
971					HandoverID: h.ID,
972					FromShift:  h.FromShiftID,
973					ToShift:    h.ToShiftID,
974					Entry:      cloneEntry(h.Entries[j]),
975				})
976			}
977		}
978		sort.Slice(rep.Incoming, func(i, j int) bool { return rep.Incoming[i].ID < rep.Incoming[j].ID })
979		for k := range rep.Results {
980			sort.Slice(rep.Results[k], func(i, j int) bool { return rep.Results[k][i].HandoverID < rep.Results[k][j].HandoverID })
981		}
982		return rep, nil
983	}
